/**
 * Create Repetition Block Action
 *
 * Action for wrapping selected steps in a repetition block.
 *
 * Requirements:
 * - Requirement 4: Create repetition blocks from selected steps
 */

import type { KRD, RepetitionBlock } from "../../types/krd";
import { createdItemTarget } from "../focus-rules";
import { defaultIdProvider } from "../providers/id-provider";
import type { ItemId } from "../providers/item-id";
import type { WorkoutState } from "../workout-actions";
import { createUpdateWorkoutAction } from "../workout-actions";
import { extractStructuredWorkout } from "./_helpers/extract-workout";
import {
  calculateInsertPosition,
  extractSteps,
  reindexSteps,
} from "./repetition-block-helpers";

/**
 * Creates a repetition block from selected step indices
 */
export const createRepetitionBlockAction = (
  krd: KRD,
  stepIndices: Array<number>,
  repeatCount: number,
  state: WorkoutState
): Partial<WorkoutState> => {
  const workout = extractStructuredWorkout(krd);
  if (!workout || stepIndices.length === 0 || repeatCount < 2) {
    return {};
  }

  const selectedIndices = new Set(stepIndices);

  const { stepsToWrap, remainingSteps, insertPosition } = extractSteps(
    workout,
    selectedIndices
  );

  if (insertPosition === null || stepsToWrap.length === 0) {
    return {};
  }

  // Block and nested step ids all come from `defaultIdProvider()` so the
  // in-memory ItemId contract is uniform: every step and every block is
  // referenced by the same UUID v4 shape the focus / selection system
  // uses (no Math.random — design decision 1).
  const repetitionBlock: RepetitionBlock = {
    id: defaultIdProvider(),
    repeatCount,
    steps: stepsToWrap,
  };
  const adjustedPosition = calculateInsertPosition(
    workout,
    insertPosition,
    selectedIndices
  );

  const newSteps = [
    ...remainingSteps.slice(0, adjustedPosition),
    repetitionBlock,
    ...remainingSteps.slice(adjustedPosition),
  ];

  const updatedWorkout = { ...workout, steps: reindexSteps(newSteps) };
  const updatedKrd: KRD = {
    ...krd,
    extensions: { ...krd.extensions, structured_workout: updatedWorkout },
  };

  return {
    ...createUpdateWorkoutAction(updatedKrd, state),
    pendingFocusTarget: createdItemTarget(repetitionBlock.id as ItemId),
  };
};
